using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class BattleSceneSetup : ScriptableObject
{
	[SerializeField]
	protected MapHandler mapHandler;

	[SerializeField]
	private bool battleSetup;

	[SerializeField]
	[HideIf("battleSetup")]
	protected VoidEvent OnPlayBGM;

	public virtual void SetupScene()
	{
		mapHandler.ResetCurrentRewardCounter();
		PlayBGM();
	}

	public virtual void PlayBGM()
	{
		OnPlayBGM.Raise();
	}
}
